import {foundryStoryProgress,FOUNDRY_STORY_ENDINGS,FOUNDRY_STORY_GOLD} from './expedition-foundry-story.mjs';
import {GEAR} from './expedition-data.mjs';import {equipmentStats} from './expedition-equipment-view.mjs';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function foundryStoryView(g){
 const p=foundryStoryProgress(g),ending=p.ending&&FOUNDRY_STORY_ENDINGS[p.ending];
 return `<section class="guild-panel foundry-story" data-guild-pane="journey"><p class="eyebrow">单人旅程 / 铸库归航</p><h2>替最后一班，写下归航的名字。</h2><p>从炉门到外港，把探索、带回的回答与最后一班守望串成一段旅程。三段条件计入已领取的正常远征结果，已完成的条件直接保留；路线仍可自由选择。</p><p class="story-progress" role="status">旅程 ${p.completed}/3 · ${esc(p.reason)}</p><div class="story-steps">${p.steps.map((step,i)=>`<article class="story-step" data-story-step="${step.id}"><p class="eyebrow">第${i+1}段 · ${step.done?'已完成':'尚未完成'}</p><h3>${step.title}</h3><p>${esc(step.done?step.after:step.before)}</p><p><b>交接条件：</b>${step.condition}</p><button data-journey-prepare="${step.route}">${step.route==='foundry'?'准备锈潮铸库':'准备封库守望'} →</button></article>`).join('')}</div>${ending?`<article class="story-ending" data-story-ending="${p.ending}"><p class="eyebrow">归航结局 / 已记录</p><h3>${ending.name}</h3><p>${ending.text}</p><p>${FOUNDRY_STORY_GOLD}金币与${GEAR[ending.gear].name}已作为一次旅程奖励入库；之后通关仍按路线正常结算。</p><button data-guild-tab="equipment">去仓库分配装备 →</button></article>`:`<h3>归航之后，留下什么？</h3><p>可先阅读三个结局。完成三段条件后，选择一次交付：获得${FOUNDRY_STORY_GOLD}金币与该结局指定的一件装备，结局随公会备份保存。装备入仓后再分配，不额外发经验。</p><div class="story-endings">${Object.entries(FOUNDRY_STORY_ENDINGS).map(([id,e])=>`<article class="story-ending" data-story-choice="${id}"><h3>${e.name}</h3><p>${e.text}</p><p><b>${GEAR[e.gear].name} + ${FOUNDRY_STORY_GOLD}金币</b></p><small>${esc(equipmentStats(e.gear))}</small><button data-foundry-story-end="${id}" ${p.canClaim?'':'disabled'}>选择此结局并领取 · ${GEAR[e.gear].name}</button></article>`).join('')}</div>`}<p class="muted">结局记录用于这段单人故事与定向装备选择。正常远征奖励另算，实验、试演与历史重演不完成旅程，也不发放旅程奖励。</p></section>`;
}
